local TrebuchetMaker = {}
local PRODUCTS = {
    traction_trebuchet = { name = "Vlečni trebuchet", woodCost = 8, ropeCost = 4, leatherCost = 2, time = 8, cost = 500, attack = 50, range = 250, durability = 45, description = "Vlečni trebuchet z ročno napetostjo." },
    counterweight_trebuchet = { name = "Protitežni trebuchet", woodCost = 12, ironCost = 4, stoneCost = 5, ropeCost = 5, leatherCost = 2, time = 12, cost = 1400, attack = 80, range = 320, durability = 60, prestige = 4, description = "Protitežni trebuchet z veliko močjo." },
    war_trebuchet = { name = "Vojaški trebuchet", woodCost = 14, ironCost = 6, stoneCost = 6, ropeCost = 6, leatherCost = 3, time = 16, cost = 2800, attack = 120, range = 380, durability = 80, prestige = 8, happiness = 1, description = "Vojaški trebuchet za velike oblege." },
    great_trebuchet = { name = "Veliki trebuchet", woodCost = 16, ironCost = 7, steelCost = 2, stoneCost = 8, ropeCost = 7, leatherCost = 3, time = 20, cost = 4800, attack = 170, range = 440, durability = 100, prestige = 14, happiness = 2, description = "Veliki trebuchet za najmočnejša obleganja." },
    silver_adorned_trebuchet = { name = "Srebrno okrašen trebuchet", woodCost = 16, ironCost = 6, steelCost = 3, silverCost = 2, stoneCost = 8, ropeCost = 7, leatherCost = 3, time = 23, cost = 7500, attack = 210, range = 480, durability = 120, prestige = 25, happiness = 4, description = "Trebuchet s srebrnim okrasjem za kraljevo vojsko." },
    royal_grand_trebuchet = { name = "Kraljevski veliki trebuchet", woodCost = 22, ironCost = 10, steelCost = 5, goldCost = 3, silverCost = 2, stoneCost = 10, ropeCost = 10, leatherCost = 5, jewelCost = 1, time = 30, cost = 15000, attack = 300, range = 600, durability = 180, prestige = 70, happiness = 14, description = "Veliki kraljevski trebuchet z zlatim in draguljnim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Trebuchetska delavnica", cost = { gold = 550, wood = 250, stone = 200 }, upkeep = 14, qualityBonus = 5 },
    siege_yard = { name = "Oblegovalno dvorišče", cost = { gold = 1800, wood = 450, stone = 450, iron = 12 }, upkeep = 35, qualityBonus = 18 },
    counterweight_room = { name = "Protitežna soba", cost = { gold = 4000, wood = 550, stone = 800, silver = 50, stone2 = 10 }, upkeep = 80, qualityBonus = 30 },
    royal_trebuchet_atelier = { name = "Kraljevski atelje trebuchetov", cost = { gold = 17000, wood = 1200, stone = 1800, gold = 250, jewel = 30 }, upkeep = 350, qualityBonus = 55, prestigeBonus = 55 },
}
TrebuchetMaker.woodStock = 28; TrebuchetMaker.ironStock = 14; TrebuchetMaker.steelStock = 10; TrebuchetMaker.stoneStock = 14; TrebuchetMaker.ropeStock = 14; TrebuchetMaker.leatherStock = 10; TrebuchetMaker.silverStock = 8; TrebuchetMaker.goldStock = 6; TrebuchetMaker.jewelStock = 6
TrebuchetMaker.productStock = {}; TrebuchetMaker.buildings = {}; TrebuchetMaker.maker = nil; TrebuchetMaker.activeMaking = {}; TrebuchetMaker.totalProducts = 0; TrebuchetMaker.dayTimer = 0
function TrebuchetMaker.init() TrebuchetMaker.woodStock=28; TrebuchetMaker.ironStock=14; TrebuchetMaker.steelStock=10; TrebuchetMaker.stoneStock=14; TrebuchetMaker.ropeStock=14; TrebuchetMaker.leatherStock=10; TrebuchetMaker.silverStock=8; TrebuchetMaker.goldStock=6; TrebuchetMaker.jewelStock=6; TrebuchetMaker.productStock={}; TrebuchetMaker.buildings={}; TrebuchetMaker.maker=nil; TrebuchetMaker.activeMaking={}; TrebuchetMaker.totalProducts=0; TrebuchetMaker.dayTimer=0; print("[TrebuchetMaker] Royal Trebuchet Maker System initialized (6 products, 4 buildings)") end
function TrebuchetMaker.hireMaker(n,s) s=s or math.random(55,95); local c=750+s*15; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TrebuchetMaker.maker={name=n or ("Trebuchetar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trebuchetar najet: %s (spretnost: %d)",TrebuchetMaker.maker.name,s),"success") end; return true end
function TrebuchetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TrebuchetMaker.build(id) local ok,e=TrebuchetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TrebuchetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TrebuchetMaker.getQualityBonus() local b=0; for _,bd in ipairs(TrebuchetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TrebuchetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and TrebuchetMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and TrebuchetMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and TrebuchetMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.stoneCost and TrebuchetMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.ropeCost and TrebuchetMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.leatherCost and TrebuchetMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TrebuchetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TrebuchetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TrebuchetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #TrebuchetMaker.buildings==0 then return false,"Potrebna delavnica" end; if not TrebuchetMaker.maker then return false,"Potreben trebuchetar" end; return true end
function TrebuchetMaker.make(pt,qty) qty=qty or 1; local ok,e=TrebuchetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then TrebuchetMaker.woodStock=TrebuchetMaker.woodStock-d.woodCost*qty end; if d.ironCost then TrebuchetMaker.ironStock=TrebuchetMaker.ironStock-d.ironCost*qty end; if d.steelCost then TrebuchetMaker.steelStock=TrebuchetMaker.steelStock-d.steelCost*qty end; if d.stoneCost then TrebuchetMaker.stoneStock=TrebuchetMaker.stoneStock-d.stoneCost*qty end; if d.ropeCost then TrebuchetMaker.ropeStock=TrebuchetMaker.ropeStock-d.ropeCost*qty end; if d.leatherCost then TrebuchetMaker.leatherStock=TrebuchetMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TrebuchetMaker.silverStock=TrebuchetMaker.silverStock-d.silverCost*qty end; if d.goldCost then TrebuchetMaker.goldStock=TrebuchetMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TrebuchetMaker.jewelStock=TrebuchetMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if TrebuchetMaker.maker then t=math.max(1,t-math.floor(TrebuchetMaker.maker.skill/12)) end; table.insert(TrebuchetMaker.activeMaking,{id="trebuchet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,range=d.range or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TrebuchetMaker.completeMaking(m) local q=1.0+(TrebuchetMaker.getQualityBonus()/100); if TrebuchetMaker.maker then q=q+(TrebuchetMaker.maker.skill/150) end; q=math.min(2.5,q); TrebuchetMaker.productStock[m.productType]=(TrebuchetMaker.productStock[m.productType] or 0)+m.quantity; TrebuchetMaker.totalProducts=TrebuchetMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TrebuchetMaker.maker then TrebuchetMaker.maker.itemsMade=TrebuchetMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TrebuchetMaker.maker.skill=math.min(100,TrebuchetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trebuchet izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"trebuchet.completed",{productName=m.productName,attack=m.attack,range=m.range,durability=m.durability}) end end
function TrebuchetMaker.update(dt) if not _G.state then return end; TrebuchetMaker.dayTimer=TrebuchetMaker.dayTimer+dt; if TrebuchetMaker.dayTimer>=30 then TrebuchetMaker.dayTimer=0; for i=#TrebuchetMaker.activeMaking,1,-1 do local m=TrebuchetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TrebuchetMaker.completeMaking(m); table.remove(TrebuchetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TrebuchetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TrebuchetMaker.maker then tu=tu+28 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TrebuchetMaker.getStats() return {woodStock=TrebuchetMaker.woodStock,ironStock=TrebuchetMaker.ironStock,steelStock=TrebuchetMaker.steelStock,stoneStock=TrebuchetMaker.stoneStock,ropeStock=TrebuchetMaker.ropeStock,leatherStock=TrebuchetMaker.leatherStock,silverStock=TrebuchetMaker.silverStock,goldStock=TrebuchetMaker.goldStock,jewelStock=TrebuchetMaker.jewelStock,productStock=TrebuchetMaker.productStock,numBuildings=#TrebuchetMaker.buildings,hasMaker=TrebuchetMaker.maker~=nil,makerName=TrebuchetMaker.maker and TrebuchetMaker.maker.name or "—",makerSkill=TrebuchetMaker.maker and TrebuchetMaker.maker.skill or 0,activeMaking=#TrebuchetMaker.activeMaking,totalProducts=TrebuchetMaker.totalProducts} end
return TrebuchetMaker
